// th18_s7_b5 — TH18 v1.00a st07bs.ecl.txt Boss3:317-375 + Boss3_at:377-402
// 独立无体碰外壳：control 在 (0,0)；真实 Boss 在 120 帧缓冲后创建于 (0,128)。
// 源计时从 Boss3 入口 timerReset 起算；活动槽 0 超时 3600 帧，本卡 clock 到 3600 即停。

const TIME_LIMIT: int = 3780;
const OPENING_BUFFER: int = 120;

// 源 etSprite(0/1, 12, 14)：TH18 type12=ARROWHEAD(544)，色号 14。
const ARROWHEAD_COLOR: int = 14;

// 源 Boss3_at 的 EX 链（三记录 async=0，顺序执行）：
//   ANIM(a=1) → VELTIME(a=60, r=4.0, s=当前角) → ANGLE_ACCEL(a=30, r=-0.1, s=±1°)。
// 出生动画的减速/无判定/动画等待按公共口径整体省略；ANIM 的 -4*velocity 退位移
// 不省，已并入下面 fire 的出生位置。VELTIME 方向取进入时弹角，故只加速不改向。
xformdef TH18_VEL_ANGLE(delta: fx, omega: angle) {
    @60 set_accel(delta);   // VELTIME：60 帧把标量速从出生 v 线性推到 4.0
    set_accel(-0.1fx);      // ANGLE_ACCEL：30 帧速度 -0.1/帧
    set_ang_vel(omega);     //              同时 ±1°/帧
    wait(30);
    set_accel(0fx);
    set_ang_vel(0deg);
}

// 源 Boss3_at：etNew(slot) 后 etCount(5,8)、mode3 固定方向环、etAngle(G,F)、
// etSpeed(1.2,0)、etDist(32)、etOffset(0,-24)，循环 etOn + wait(10)。
// 两路 async（slot0/1）各自持发射器；目标用逐颗 fire 保留层外路内的创建序、
// 每层速度/出生退位移与每弹独立 xform 参数。
async sub boss3_at(turn_step: angle, layer_step: angle, omega: angle) {
    var base: angle = aim_player();   // 源 %G = %ANGLE_PLAYER，任务入口只读一次
    // 源 H=10000 的长循环由 3600 帧超时截断：首弹源 t=181，末弹 t=3591，共 342 波。
    for k in 0..342 {
        for q in 0..8 {
            // 源 etSpeed(1.2, 0.0) 的首末层插值：v(q)=1.2+(0-1.2)*q/7。
            var v: fx = 1.2fx + (0fx - 1.2fx) * q / 7;
            var delta: fx = (4fx - v) / 60;   // VELTIME 斜坡 (r-old)/a
            // 源 etDist(32) 与 ANIM 退位移 -4*velocity 合成后的净出生距离。
            var d: fx = 32fx - v * 4;
            for i in 0..5 {
                // 源 mode3：alpha + R(i) + q*delta，R(i)=2πi/5。
                var a: angle = (base as int + (i * 65536) / 5 + q * (layer_step as int)) as angle;
                var sx: fx = $self_x + d * cos(a);
                var sy: fx = $self_y - 24fx + d * sin(a);   // 源 etOffset(0,-24)
                _ = fire(TH18_ARROWHEAD, ARROWHEAD_COLOR, sx, sy, v, a,
                         TH18_VEL_ANGLE(delta, omega), none);
            }
        }
        base = base + turn_step;   // 源 %G += %D：slot0 +8°/波，slot1 -8°/波
        wait(10);
    }
}

// 源移动：moveRand(60,4,1.0) + moveLimit(0,128,240,64)。
// 按 movement.md 已核 moveRand 配方复用：内区 |x|<60、y 112..144；实际限位
// x∈[-120,120]、y∈[96,160]；速度 1-k/60，每帧夹最终位置，不反弹。
// 共享槽为本卡自用（源本段未用 I/F 槽）：int0=步数，int1=段内帧钟，int3=移动激活；
// fx0/1=本步方向单位向量。
sub card_arm_next_step() {
    if self_int(3) == 0 { return; }
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    set_self_int(3, 1);
    card_arm_next_step();
}

// 源 412 方向选择：signed π 随机后按 x 分区、w%3 选侧、y 顶部/底部取 |a|/-|a|，
// 再做 ±π/2±0.05rad 护栏。目标 RNG/BAM 量化差异按公共口径。
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // 0.05rad ≈ 521.5 BAM；±π/2 的最近整数边界。
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// 逐帧推进源运动 tick，并推进段内 clock；到 3600 帧提前返回，供外层结束本段。
sub card_wait(frames: int) {
    var i: int = 0;
    while i < frames && self_int(1) < 3600 {
        wait(1);
        set_self_int(1, self_int(1) + 1);
        card_arm_next_step();
        i = i + 1;
    }
}

async sub boss3() {
    set_invuln(65535);   // 训练壳：真实敌整段无敌
    set_hitbox(24fx);    // 源 setHitbox(48,48) 普通圆 → 半径 24
    set_hurtbox(20fx);   // 源 setHurtbox(40,40) → 半径 20
    set_self_int(0, 0);
    set_self_int(1, 0);
    set_self_int(3, 0);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);

    // 源 movePosTime(60,4,0,128)：独立场景已从 (0,128) 静止起步，保留该次插值。
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    card_wait(120);   // 源 wait(120)
    card_wait(60);    // 源 moveLimit(0,128,240,64) 后 wait(60)

    // 源两路 Boss3_at(0/1, 5, 8, ±8°, ±1°, ∓0.3°) async。
    spawn boss3_at(8deg, -0.3deg, 1deg);
    spawn boss3_at(-8deg, 0.3deg, -1deg);

    // 源 Boss3_1304 ← Boss3_1440 无限循环：wait100, moveRand, wait60,
    // wait100, moveRand, wait60；源 3600 帧超时结束本段，不执行下张卡。
    loop {
        card_wait(100);
        if self_int(1) >= 3600 { return; }
        card_move_rand();
        card_wait(60);
        if self_int(1) >= 3600 { return; }
        card_wait(100);
        if self_int(1) >= 3600 { return; }
        card_move_rand();
        card_wait(60);
        if self_int(1) >= 3600 { return; }
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 18500, 0, 0, 0, boss3);   // 源 lifeSet(18500)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

